"use client";

import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox";

import { cn } from "@/lib/utils";
import { glowControlChecked } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Firefly Checkbox: a 1.25rem box with a 0.375rem corner and a warm grey
 * edge. Checked or mixed, it fills with the primary button's lit material,
 * scaled down, and the near-black tick or dash sits on the glow. Base UI
 * owns the checked state, so a controlled parent passes `checked` straight
 * through.
 */
function Checkbox({
  className,
  indeterminate,
  ...props
}: WithClassName<CheckboxPrimitive.Root.Props>) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      indeterminate={indeterminate}
      className={cn(
        "peer inline-flex size-5 shrink-0 items-center justify-center rounded-sm border border-(--control) bg-background text-primary-foreground",
        "transition-[background-color,border-color,box-shadow] duration-fast ease-out",
        "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
        "data-[disabled]:cursor-not-allowed data-[disabled]:border-(--line-strong) data-[disabled]:bg-secondary data-[disabled]:text-(--foreground-disabled)",
        glowControlChecked,
        "data-[indeterminate]:border-transparent data-[indeterminate]:bg-primary data-[indeterminate]:bg-(image:--gradient-primary) data-[indeterminate]:shadow-(--shadow-control)",
        "data-[disabled]:data-[indeterminate]:bg-secondary data-[disabled]:data-[indeterminate]:bg-none data-[disabled]:data-[indeterminate]:shadow-none data-[disabled]:data-[indeterminate]:text-(--foreground-disabled)",
        className,
      )}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        data-slot="checkbox-indicator"
        className="flex size-full items-center justify-center text-current"
      >
        {indeterminate ? (
          <svg viewBox="0 0 16 16" fill="none" aria-hidden="true" className="size-3.5">
            <path d="M4 8h8" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
          </svg>
        ) : (
          <svg viewBox="0 0 16 16" fill="none" aria-hidden="true" className="size-3.5">
            <path
              d="M3.75 8.25 6.5 11l5.75-6"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        )}
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  );
}
Checkbox.displayName = "Checkbox";

export { Checkbox };
